package com.mcnex.conversation;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;
public class GpuBenchmarkProbe extends Instrumentation {
 private JSONObject report=new JSONObject();
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void save()throws Exception{try(FileOutputStream out=getTargetContext().openFileOutput("gpu-benchmark.json",0)){out.write(report.toString().getBytes("UTF-8"));}}
 private void stage(String value)throws Exception{report.put("stage",value);save();Bundle b=new Bundle();b.putString("stage",value);sendStatus(1,b);}
 private void run(String label,boolean gpu)throws Exception{stage(label+" loading");long start=SystemClock.elapsedRealtime();try(LocalAi ai=new LocalAi(new File(getTargetContext().getFilesDir(),"model.gguf"),gpu)){long loaded=SystemClock.elapsedRealtime();stage(label+" generating");String answer=ai.explain("카메라 역광 촬영에서 HDR 기술의 의미를 검토하고 있습니다.","자동 대화 도움","assist");long end=SystemClock.elapsedRealtime();JSONObject parsed=new JSONObject(answer.substring(answer.indexOf('{'),answer.lastIndexOf('}')+1));if(!parsed.optString("kind").matches("none|term|reply"))throw new IOException("Invalid JSON output");JSONObject result=new JSONObject().put("device",ai.backend()).put("loadMs",loaded-start).put("generateMs",end-loaded).put("answer",parsed);if(gpu){long warm=SystemClock.elapsedRealtime();String next=ai.explain("카메라 역광 촬영에서 HDR 기술의 의미를 검토하고 있습니다.","자동 대화 도움","assist");result.put("warmMs",SystemClock.elapsedRealtime()-warm).put("warmAnswer",next);}report.put(label,result);save();}}
 public void onStart(){try{run("cpu",false);run("opencl",true);run("cpuAfterGpu",false);stage("litertlm checking");long liteStart=SystemClock.elapsedRealtime();try(LiteAi ai=new LiteAi(new File(getTargetContext().getFilesDir(),"model.litertlm"),getTargetContext().getCacheDir())){String text=ai.minutes("한국어 한 문장으로 답하세요.","HDR은 어떤 기술인가요?",32);if(text.isEmpty())throw new IOException("Empty LiteRT response");report.put("litertlm",new JSONObject().put("elapsedMs",SystemClock.elapsedRealtime()-liteStart).put("text",text));}report.put("ok",true);stage("complete");}catch(Exception|LinkageError e){try{report.put("ok",false).put("error",e.toString());save();}catch(Exception ignored){}}Bundle out=new Bundle();out.putString("report",report.toString());finish(report.optBoolean("ok")?-1:0,out);}
}
